from datetime import date

import pytest

from dispatch.case import scheduled


class FakeDate(date):
    """Date whose today() is pinned to the day under test."""

    @classmethod
    def today(cls):
        return cls(2025, 8, 11)


@pytest.mark.parametrize(
    "day,expected",
    [
        (11, True),  # Monday
        (12, False),
        (13, False),
        (14, False),
        (15, False),
        (16, False),
        (17, False),  # Sunday
    ],
)
def test_is_reminder_day(monkeypatch, day, expected):
    class PinnedDate(FakeDate):
        @classmethod
        def today(cls):
            return cls(2025, 8, day)

    monkeypatch.setattr(scheduled, "date", PinnedDate)

    assert scheduled._is_reminder_day() is expected

